let currentMode = 'encrypt';
        let selectedFile = null;
        /**
         * System Logging
         */
        function log(msg, color = 'text-slate-300') {
            const consoleEl = document.getElementById('console');
            const entry = document.createElement('div');
            entry.className = `log-entry ${color}`;
            entry.innerText = msg;
            consoleEl.appendChild(entry);
            consoleEl.scrollTop = consoleEl.scrollHeight;
        }
        /**
         * Tab Mode Switching
         */
        function switchMode(mode) {
            currentMode = mode;
            document.getElementById('tab-encrypt').classList.toggle('active', mode === 'encrypt');
            document.getElementById('tab-decrypt').classList.toggle('active', mode === 'decrypt');
            const btnText = document.getElementById('btn-text');
            const btnIcon = document.getElementById('btn-icon');
            const actionBtn = document.getElementById('action-btn');
            if (mode === 'encrypt') {
                btnText.innerText = 'Execute Encryption';
                if (btnIcon) btnIcon.innerHTML = '<svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"></path></svg>';
                actionBtn.className = "w-full bg-slate-900 hover:bg-black text-white font-black py-4 rounded-2xl shadow-xl transition transform active:scale-95 flex items-center justify-center gap-3 uppercase tracking-[0.2em] text-xs";
                log("Switching to Encryption Protocol...");
            } else {
                btnText.innerText = 'Execute Decryption';
                if (btnIcon) btnIcon.innerHTML = '<svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 11V7a4 4 0 118 0m-4 8v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2z"></path></svg>';
                actionBtn.className = "w-full bg-emerald-600 hover:bg-emerald-700 text-white font-black py-4 rounded-2xl shadow-xl transition transform active:scale-95 flex items-center justify-center gap-3 uppercase tracking-[0.2em] text-xs";
                log("Switching to Decryption Protocol...");
            }
        }
        /**
         * Password Visibility
         */
        function togglePass() {
            const input = document.getElementById('password');
            input.type = input.type === 'password' ? 'text' : 'password';
        }
        /**
         * File Selection Handler
         */
        function handleFileSelect(input) {
            if (input.files.length > 0) {
                selectedFile = input.files[0];
                document.getElementById('file-name-display').innerText = `BUFFERED: ${selectedFile.name.toUpperCase()} (${(selectedFile.size / 1024 / 1024).toFixed(2)} MB)`;
                document.getElementById('file-name-display').classList.add('text-emerald-500');
                log(`IO: File handle secured for ${selectedFile.name}`);
            }
        }
        /**
         * Crypto Engine: Key Setup
         */
        async function getPasswordKey(password) {
            const enc = new TextEncoder();
            return window.crypto.subtle.importKey(
                "raw",
                enc.encode(password),
                { name: "PBKDF2" },
                false,
                ["deriveKey"]
            );
        }
        async function deriveKey(passwordKey, salt, keyUsage) {
            return window.crypto.subtle.deriveKey(
                {
                    name: "PBKDF2",
                    salt: salt,
                    iterations: 100000,
                    hash: "SHA-256"
                },
                passwordKey,
                { name: "AES-GCM", length: 256 },
                false,
                keyUsage
            );
        }
        /**
         * Primary Execution Logic
         */
        async function processFile() {
            const password = document.getElementById('password').value;
            if (!selectedFile) { log("ERR: No artifact in buffer.", "text-red-500"); return; }
            if (!password) { log("ERR: Access key required.", "text-red-500"); return; }
            // Start UI Scan animation
            document.getElementById('processing-overlay').classList.remove('hidden');
            document.getElementById('scan-line').style.display = 'block';
            log(`STAGING: Initializing local ${currentMode} loop...`);
            try {
                const fileBytes = await selectedFile.arrayBuffer();
                if (currentMode === 'encrypt') {
                    // Generate Cryptographic Randomness
                    const salt = window.crypto.getRandomValues(new Uint8Array(16));
                    const iv = window.crypto.getRandomValues(new Uint8Array(12));
                    log("PROCESS: Stretching password entropy (PBKDF2)...");
                    const passwordKey = await getPasswordKey(password);
                    const aesKey = await deriveKey(passwordKey, salt, ["encrypt"]);
                    log("CIPHER: Block processing via AES-GCM-256...");
                    const encryptedContent = await window.crypto.subtle.encrypt(
                        { name: "AES-GCM", iv: iv },
                        aesKey,
                        fileBytes
                    );
                    // Package into binary blob
                    log("PACKAGING: Serializing Salt, IV, and Payload...");
                    const blob = new Blob([salt, iv, encryptedContent], { type: "application/octet-stream" });
                    downloadFile(blob, selectedFile.name + ".enc");
                    log("STATUS: Encryption cycle complete. IO Download triggered.");
                } else {
                    // Extraction
                    const salt = fileBytes.slice(0, 16);
                    const iv = fileBytes.slice(16, 28);
                    const data = fileBytes.slice(28);
                    log("PROCESS: Reconstructing key from provided salt...");
                    const passwordKey = await getPasswordKey(password);
                    const aesKey = await deriveKey(passwordKey, salt, ["decrypt"]);
                    log("CIPHER: Verifying Authentication Tag...");
                    const decryptedContent = await window.crypto.subtle.decrypt(
                        { name: "AES-GCM", iv: iv },
                        aesKey,
                        data
                    );
                    const originalName = selectedFile.name.replace(".enc", "");
                    const blob = new Blob([decryptedContent], { type: "application/octet-stream" });
                    downloadFile(blob, "decrypted_" + originalName);
                    log("STATUS: Decryption success. Integrity verified.");
                }
            } catch (e) {
                console.error(e);
                log("FATAL ERROR: Authentication Failed or Buffer Overflow.", "text-red-500");
                // Custom UI error message instead of alert
                const errorMsg = document.createElement('div');
                errorMsg.className = "fixed top-32 left-1/2 -translate-x-1/2 bg-red-600 text-white px-8 py-4 rounded-2xl shadow-2xl z-[100] font-black uppercase tracking-widest text-xs animate-pulse";
                errorMsg.innerText = "Vault Access Denied: Check Password Integrity";
                document.body.appendChild(errorMsg);
                setTimeout(() => errorMsg.remove(), 5000);
            } finally {
                document.getElementById('processing-overlay').classList.add('hidden');
                document.getElementById('scan-line').style.display = 'none';
            }
        }
        function downloadFile(blob, filename) {
            const url = window.URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = filename;
            document.body.appendChild(a);
            a.click();
            window.URL.revokeObjectURL(url);
            document.body.removeChild(a);
        }
        /**
         * Drag & Drop Setup
         */
        const dropZone = document.getElementById('drop-zone');
        dropZone.addEventListener('dragover', (e) => { e.preventDefault(); dropZone.classList.add('dragover'); });
        dropZone.addEventListener('dragleave', () => dropZone.classList.remove('dragover'));
        dropZone.addEventListener('drop', (e) => {
            e.preventDefault();
            dropZone.classList.remove('dragover');
            if (e.dataTransfer.files.length) {
                document.getElementById('file-input').files = e.dataTransfer.files;
                handleFileSelect(document.getElementById('file-input'));
            }
        });
        /**
         * UI Interactions
         */
